-- Esquema do banco do Projeto Salvação (PostgreSQL / Supabase) — estado atual.
-- Extraído do banco em produção. Para criar as tabelas use: python manage.py migrate
-- Depois rode: python manage.py protege_banco   (liga a proteção RLS no Supabase)

CREATE TABLE public."core_turma" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nome" character varying(80) NOT NULL,
    "publico" character varying(80) NOT NULL,
    "dias" character varying(80) NOT NULL,
    "horario" character varying(40) NOT NULL,
    "ordem" smallint NOT NULL,
    "modalidade" character varying(12) NOT NULL,
    CONSTRAINT "core_turma_pkey" PRIMARY KEY (id),
    CONSTRAINT "core_turma_ordem_check" CHECK ((ordem >= 0))
);

CREATE TABLE public."core_aluno" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nome" character varying(120) NOT NULL,
    "nascimento" date NOT NULL,
    "telefone" character varying(20) NOT NULL,
    "responsavel" character varying(120) NOT NULL,
    "foto" character varying(100) NOT NULL,
    "faixa" character varying(20) NOT NULL,
    "grau" smallint NOT NULL,
    "inicio" date NOT NULL,
    "status" character varying(10) NOT NULL,
    "observacoes" text NOT NULL,
    "criado_em" timestamp with time zone NOT NULL,
    "turma_id" bigint,
    CONSTRAINT "core_aluno_pkey" PRIMARY KEY (id),
    CONSTRAINT "core_aluno_turma_id_500cf1ed_fk_core_turma_id" FOREIGN KEY (turma_id) REFERENCES core_turma(id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "core_aluno_grau_check" CHECK ((grau >= 0))
);
CREATE INDEX core_aluno_turma_id_500cf1ed ON public.core_aluno USING btree (turma_id);

CREATE TABLE public."core_graduacao" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "faixa" character varying(20) NOT NULL,
    "grau" smallint NOT NULL,
    "data" date NOT NULL,
    "observacao" character varying(200) NOT NULL,
    "aluno_id" bigint NOT NULL,
    CONSTRAINT "core_graduacao_pkey" PRIMARY KEY (id),
    CONSTRAINT "core_graduacao_aluno_id_1bae00c2_fk_core_aluno_id" FOREIGN KEY (aluno_id) REFERENCES core_aluno(id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "core_graduacao_grau_check" CHECK ((grau >= 0))
);
CREATE INDEX core_graduacao_aluno_id_1bae00c2 ON public.core_graduacao USING btree (aluno_id);

CREATE TABLE public."core_presenca" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "data" date NOT NULL,
    "aluno_id" bigint NOT NULL,
    CONSTRAINT "core_presenca_aluno_id_data_fe7f3adc_uniq" UNIQUE (aluno_id, data),
    CONSTRAINT "core_presenca_pkey" PRIMARY KEY (id),
    CONSTRAINT "core_presenca_aluno_id_5c145459_fk_core_aluno_id" FOREIGN KEY (aluno_id) REFERENCES core_aluno(id) DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX core_presenca_aluno_id_5c145459 ON public.core_presenca USING btree (aluno_id);
CREATE UNIQUE INDEX core_presenca_aluno_id_data_fe7f3adc_uniq ON public.core_presenca USING btree (aluno_id, data);

CREATE TABLE public."core_interessado" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nome" character varying(120) NOT NULL,
    "telefone" character varying(20) NOT NULL,
    "idade" smallint,
    "mensagem" text NOT NULL,
    "contatado" boolean NOT NULL,
    "criado_em" timestamp with time zone NOT NULL,
    CONSTRAINT "core_interessado_pkey" PRIMARY KEY (id),
    CONSTRAINT "core_interessado_idade_check" CHECK ((idade >= 0))
);

CREATE TABLE public."core_doacao" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "doador" character varying(120) NOT NULL,
    "valor" numeric(9,2) NOT NULL,
    "data" date NOT NULL,
    "forma" character varying(10) NOT NULL,
    "observacao" character varying(200) NOT NULL,
    "criado_em" timestamp with time zone NOT NULL,
    CONSTRAINT "core_doacao_pkey" PRIMARY KEY (id)
);

CREATE TABLE public."core_assinatura" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nome" character varying(120) NOT NULL,
    "titulo" character varying(160) NOT NULL,
    "imagem" text NOT NULL,
    CONSTRAINT "core_assinatura_pkey" PRIMARY KEY (id)
);
